{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.saleOrderItems\') AS saleOrderItems, JSON_EXTRACT_ARRAY(saleorderdto, \'$.shippingPackages\') AS shippingPackages, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.pincode\') AS PINCODE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.name\') AS name, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.updated\') AS int)), \"Asia/Kolkata\") AS SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.currencyCode\') AS currency, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.city\') AS city, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.state\') AS state, JSON_EXTRACT_SCALAR(saleorderdto, \'$.status\') AS ORDER_STATUS, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_Date, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.cod\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_method FROM MAPLEMONK.uc_beastlife_GET_ORDERS_BY_IDS ; CREATE OR REPLACE TEMPORARY TABLE temp_order_related AS SELECT ed.PINCODE as pincode, ed.marketplace as marketplace, ed.source as source, ed.order_id as ordeR_id, ed.reference_code reference_code, ed.phone phone, ed.name name, ed.email email, ed.SHIPPING_LAST_UPDATE_DATE SHIPPING_LAST_UPDATE_DATE, REGEXP_REPLACE(JSON_EXTRACT_SCALAR(item, \'$.itemSku\'), \'-$\', \'\') AS sku, JSON_EXTRACT_SCALAR(item, \'$.sellerSkuCode\') AS Marketplace_sku, JSON_EXTRACT_SCALAR(item, \'$.channelProductId\') AS product_id, JSON_EXTRACT_SCALAR(item, \'$.itemName\') AS product_name, ed.currency currency, ed.city city, ed.state state, JSON_EXTRACT_SCALAR(item, \'$.statusCode\') as order_status, ed.order_Date ordeR_date, CAST(JSON_EXTRACT_SCALAR(item, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, CAST(JSON_EXTRACT_SCALAR(item, \'$.packetNumber\') AS FLOAT64) AS SUBORDER_QUANTITY, CAST(JSON_EXTRACT_SCALAR(item, \'$.discount\') AS FLOAT64) AS discount, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalIntegratedGst\') AS FLOAT64) AS tax, CAST(JSON_EXTRACT_SCALAR(item, \'$.sellingPrice\') AS FLOAT64) AS SELLING_PRICE, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageCode\') AS shippingPackageCode, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageStatus\') AS shippingPackageStatus, JSON_EXTRACT_SCALAR(item, \'$.code\') AS saleOrderItemCode, CAST(JSON_EXTRACT_SCALAR(item, \'$.id\') AS STRING) AS SALES_ORDER_ITEM_ID, JSON_EXTRACT_SCALAR(item, \'$.facilityName\') AS warehouse_name, JSON_EXTRACT_SCALAR(shippingPackages,\'$.trackingNumber\') AS AWB, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceDate\') AS int)), \"Asia/Kolkata\") AS invoiceDate, JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceCode\') invoiceCode, ed.payment_mode, ed.payment_method FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.saleOrderItems) AS item LEFT JOIN UNNEST(ed.shippingPackages) AS shippingPackages; CREATE OR REPLACE TEMPORARY TABLE temp_shipping_related AS WITH extracted_items AS ( SELECT REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.status\'), \'\"\', \'\') AS shipping_status, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.dispatched\') AS int)), \"Asia/Kolkata\") AS dispatched, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.delivered\') AS int)), \"Asia/Kolkata\") AS delivered, JSON_EXTRACT_SCALAR(A, \'$.code\') AS shippingPackageCode, c.order_id, JSON_EXTRACT(A, \'$.items\') AS items FROM temp_extracted_data c LEFT JOIN UNNEST(c.shippingPackages) A ) SELECT c.*, cast(JSON_EXTRACT_SCALAR(value, \'$.quantity\') AS int64) AS shippedQuantity, REGEXP_REPLACE(JSON_EXTRACT_SCALAR(value, \'$.itemSku\'), \'-$\', \'\') AS itemSku, FROM extracted_items c left join UNNEST(REGEXP_EXTRACT_ALL(items, r\'\{[^{}]+\}\')) AS value; CREATE OR REPLACE TEMPORARY TABLE temp_returns AS WITH extracted_return_data AS ( SELECT ed.order_id, ed.reference_code, JSON_EXTRACT_ARRAY(A, \'$.returnItems\') AS returnItems FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.returns) AS A ) SELECT erd.order_id AS ordeR_id, erd.reference_code, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS saleOrderItemCode, REGEXP_REPLACE(REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\'), \'-$\', \'\') AS itemSku FROM extracted_return_data erd LEFT JOIN UNNEST(erd.returnItems) AS B WHERE REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') IS NOT NULL; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_UNICOMMERCE_fact_items_intermediate_final AS WITH phone_stats AS ( SELECT SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), \'[^a-zA-Z0-9]\', \'\'), -10) AS clean_phone, MIN(order_date) AS first_order_date, ARRAY_AGG(product_name ORDER BY order_date ASC LIMIT 1)[OFFSET(0)] AS acquisition_product FROM temp_order_related WHERE phone IS NOT NULL GROUP BY 1 ), order_counts AS ( SELECT order_id, sku, COUNT(*) AS sku_order_count FROM temp_order_related GROUP BY 1, 2 ) SELECT o.pincode, o.marketplace, o.source, o.order_id, o.reference_code, o.phone, o.name, o.email, o.SHIPPING_LAST_UPDATE_DATE, o.sku, o.Marketplace_sku, o.product_id, o.product_name, o.currency, o.city, o.state, o.ORDER_STATUS, o.invoiceCode, o.invoiceDate, o.order_date, o.shipping_price, CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN SAFE_DIVIDE(s.shippedQuantity, oc.sku_order_count) WHEN LOWER(o.marketplace) LIKE \'%tata%\' THEN o.SUBORDER_QUANTITY / 1000 WHEN CAST(o.SUBORDER_QUANTITY AS INT64) = 0 THEN 1 ELSE o.SUBORDER_QUANTITY END AS SUBORDER_QUANTITY, o.discount, o.tax, IFNULL(o.SELLING_PRICE, 0) + IFNULL(o.shipping_price, 0) AS SELLING_PRICE, o.shippingPackageCode, o.shippingPackageStatus, o.saleOrderItemCode, o.SALES_ORDER_ITEM_ID, o.AWB, o.warehouse_name, o.payment_mode, o.payment_method, s.courier, s.shipping_status, s.shippedQuantity, s.dispatched AS Dispatch_date, s.delivered AS Delivered_Date, CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END AS return_flag, CASE WHEN r.itemSku IS NOT NULL THEN CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END ELSE 0 END AS return_quantity, CASE WHEN o.order_status = \'CANCELLED\' THEN CASE WHEN LOWER(o.marketplace) LIKE \'%myntra%\' THEN s.shippedQuantity ELSE o.SUBORDER_QUANTITY END ELSE 0 END AS cancelled_quantity, CASE WHEN o.order_date = ps.first_order_date THEN \'New\' ELSE \'Repeat\' END AS new_customer_flag, ps.acquisition_product, CASE WHEN UPPER(o.order_status) = \'COMPLETE\' THEN DATE_DIFF(CAST(s.delivered AS DATE), CAST(o.order_date AS DATE), DAY) ELSE DATE_DIFF(CURRENT_DATE, CAST(o.order_date AS DATE), DAY) END AS days_in_shipment FROM temp_order_related o LEFT JOIN order_counts oc ON o.order_id = oc.order_id AND o.sku = oc.sku LEFT JOIN phone_stats ps ON SUBSTR(REGEXP_REPLACE(REPLACE(o.phone, \' \', \'\'), \'[^a-zA-Z0-9]\', \'\'), -10) = ps.clean_phone LEFT JOIN temp_shipping_related s ON o.shippingPackageCode = s.shippingPackageCode AND o.sku = s.itemSku AND o.order_id = s.order_id LEFT JOIN temp_returns r ON r.saleOrderItemCode = o.saleOrderItemCode AND r.order_id = o.order_id; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_customerID_test_Final AS WITH new_phone_numbers AS ( SELECT contact_num, 9700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), \'[^a-zA-Z0-9]\', \'\'), -10) AS contact_num FROM MAPLEMONK.beastlife_UNICOMMERCE_fact_items_intermediate_final ) ), base AS ( SELECT DISTINCT COALESCE( p.contact_num, SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'), \'[^a-zA-Z0-9]\', \'\'), -10) ) AS contact_num, e.email, p.maple_monk_id FROM ( SELECT REPLACE(phone, \' \', \'\') AS contact_num, email FROM MAPLEMONK.beastlife_UNICOMMERCE_fact_items_intermediate_final ) e LEFT JOIN new_phone_numbers p ON p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'), \'[^a-zA-Z0-9]\', \'\'), -10) ), unmatched_emails AS ( SELECT contact_num, email, 9800000000 + ROW_NUMBER() OVER (ORDER BY email ASC) AS new_id FROM base WHERE maple_monk_id IS NULL AND email IS NOT NULL AND email <> \'\' ) SELECT b.contact_num, b.email, CASE WHEN b.email IS NOT NULL AND b.email <> \'\' THEN MIN(COALESCE(b.maple_monk_id, u.new_id)) OVER (PARTITION BY b.email) ELSE COALESCE(b.maple_monk_id, u.new_id) END AS maple_monk_id FROM base b LEFT JOIN unmatched_emails u ON b.contact_num = u.contact_num AND b.email = u.email WHERE COALESCE(b.contact_num, b.email) IS NOT NULL; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_unicommerce_fact_items AS WITH customer_map AS ( SELECT DISTINCT REPLACE(contact_num, \' \', \'\') AS phone, maple_monk_id FROM MAPLEMONK.beastlife_customerID_test_Final ), acquisition AS ( SELECT c.maple_monk_id, MIN(o.order_date) AS acquisition_date FROM MAPLEMONK.beastlife_UNICOMMERCE_fact_items_intermediate_final o JOIN customer_map c ON REPLACE(c.phone, \' \', \'\') = REPLACE(o.phone, \' \', \'\') WHERE o.order_date IS NOT NULL GROUP BY 1 ) SELECT c.maple_monk_id AS customer_id, o.*, a.acquisition_date FROM MAPLEMONK.beastlife_UNICOMMERCE_fact_items_intermediate_final o LEFT JOIN customer_map c ON REPLACE(c.phone, \' \', \'\') = REPLACE(o.phone, \' \', \'\') LEFT JOIN acquisition a ON c.maple_monk_id = a.maple_monk_id WHERE o.order_date IS NOT NULL; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_unicommerce_fact_items_TEMP_Category AS SELECT fi.*, p.SKUCODE AS SKU_CODE, UPPER(p.PRODUCT_name) AS PRODUCT_NAME_Final, UPPER(p.CATEGORY) AS Product_Category, UPPER(p.SUB_CATEGORY) AS Product_Sub_Category, UPPER(p.commonsku) AS commonsku FROM MAPLEMONK.beastlife_unicommerce_fact_items fi LEFT JOIN ( SELECT skucode, CAST(NULL AS STRING) AS commonsku, CAST(name AS STRING) AS PRODUCT_name, CAST(category AS STRING) AS category, CAST(sub_category AS STRING) AS sub_category, ROW_NUMBER() OVER (PARTITION BY REPLACE(skucode, \' \', \'\') ORDER BY 1) AS rw FROM MAPLEMONK.sku_master ) p ON LOWER(REPLACE(fi.sku, \' \', \'\')) = LOWER(REPLACE(p.skucode, \' \', \'\')) AND p.rw = 1; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_unicommerce_fact_items AS SELECT * EXCEPT (rw1) FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY reference_code, saleorderitemcode ORDER BY SHIPPING_LAST_UPDATE_DATE DESC ) AS rw1 FROM MAPLEMONK.beastlife_unicommerce_fact_items_TEMP_Category ) WHERE rw1 = 1; CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data_return AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns.returnItems\') AS returnItems, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS Marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS Source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, DATETIME(TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS INT64)), \"Asia/Kolkata\") AS order_date FROM ( SELECT errors, message, warnings, successful, saleorderdto, refreshenabled, failedorderfetch FROM MAPLEMONK.uc_beastlife_GET_ORDERS_BY_IDS ); CREATE OR REPLACE TEMPORARY TABLE temp_return_data AS SELECT ed.marketplace, ed.source, ed.order_id, ed.phone, ed.email, ed.order_date, ed.reference_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.code\'), \'\"\', \'\') AS return_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.statusCode\'), \'\"\', \'\') AS return_status, DATETIME(TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(A, \'$.inventoryReceivedDate\') AS INT64)), \"Asia/Kolkata\") AS inventory_received_date, DATETIME(TIMESTAMP_MILLIS(CAST(JSON_EXTRACT_SCALAR(A, \'$.returnCompletedDate\') AS INT64)), \"Asia/Kolkata\") AS return_complete_date, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.returnInvoiceDisplayCode\'), \'\"\', \'\') AS return_invoice_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS return_courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.providerStatus\'), \'\"\', \'\') AS return_provider_shipping_status, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.trackingNumber\'), \'\"\', \'\') AS return_tracking_number, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.type\'), \'\"\', \'\') AS return_type FROM temp_extracted_data_return ed LEFT JOIN UNNEST(ed.returns) AS A; CREATE OR REPLACE TEMPORARY TABLE temp_return_items AS SELECT ed.order_id, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS sale_order_item_code, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\') AS item_sku, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemname\'), \'\"\', \'\') AS item_name, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.inventoryType\'), \'\"\', \'\') AS inventory_type FROM temp_extracted_data_return ed LEFT JOIN UNNEST(ed.returnItems) AS B; CREATE OR REPLACE TABLE MAPLEMONK.beastlife_UNICOMMERCE_RETURNS_INTERMEDIATE AS SELECT rd.marketplace, rd.source, rd.order_id, rd.phone, rd.email, rd.order_date, rd.reference_code, rd.return_display_code, rd.return_status, rd.inventory_received_date, rd.return_complete_date, rd.return_invoice_display_code, rd.return_courier, rd.return_provider_shipping_status, rd.return_tracking_number, rd.return_type, ri.sale_order_item_code, ri.item_sku, ri.item_name, ri.inventory_type FROM temp_return_data rd LEFT JOIN temp_return_items ri ON rd.order_id = ri.order_id;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            